package com.marvinight.myammo;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(MyAmmoConfig.GROUP)
public interface MyAmmoConfig extends Config
{
	String GROUP = "myammohighlighter";

	@ConfigItem(
		keyName = "onlyMine",
		name = "Only my drops",
		description = "Only highlight ammo the game says belongs to you (not other players' bolts)",
		position = 1
	)
	default boolean onlyMine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackThrown",
		name = "Include thrown weapons",
		description = "Also highlight darts, knives, javelins etc. you have wielded",
		position = 2
	)
	default boolean trackThrown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "extraItems",
		name = "Extra items",
		description = "Comma-separated item names to always highlight, wildcards allowed (e.g. *bolts*, Rune arrow)",
		position = 3
	)
	default String extraItems()
	{
		return "";
	}

	@Alpha
	@ConfigItem(
		keyName = "tileColor",
		name = "Tile color",
		description = "Outline color for tiles with your ammo",
		position = 4
	)
	default Color tileColor()
	{
		return new Color(0, 255, 140, 220);
	}

	@ConfigItem(
		keyName = "fillTile",
		name = "Fill tile",
		description = "Shade the tile as well as outlining it",
		position = 5
	)
	default boolean fillTile()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showText",
		name = "Show name and count",
		description = "Draw the ammo name and quantity above the tile",
		position = 6
	)
	default boolean showText()
	{
		return true;
	}
}

package com.marvinight.myammo;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class MyAmmoOverlay extends Overlay
{
	private final Client client;
	private final MyAmmoPlugin plugin;
	private final MyAmmoConfig config;

	@Inject
	MyAmmoOverlay(Client client, MyAmmoPlugin plugin, MyAmmoConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Color color = config.tileColor();
		Color fill = config.fillTile()
			? new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.min(60, color.getAlpha()))
			: new Color(0, 0, 0, 0);

		// Combine stacks of the same ammo on one tile into one label.
		Map<Tile, Map<String, Integer>> byTile = new HashMap<>();
		for (MyAmmoPlugin.GroundAmmo ammo : plugin.getGroundAmmo())
		{
			if (ammo.getTile().getPlane() != client.getPlane())
			{
				continue;
			}
			byTile.computeIfAbsent(ammo.getTile(), t -> new HashMap<>())
				.merge(ammo.getName(), ammo.getItem().getQuantity(), Integer::sum);
		}

		for (Map.Entry<Tile, Map<String, Integer>> entry : byTile.entrySet())
		{
			LocalPoint lp = entry.getKey().getLocalLocation();
			if (lp == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(g, poly, color, fill, new BasicStroke(2f));
			}

			if (config.showText())
			{
				int z = 20;
				for (Map.Entry<String, Integer> item : entry.getValue().entrySet())
				{
					String text = item.getKey() + " (" + item.getValue() + ")";
					Point p = Perspective.getCanvasTextLocation(client, g, lp, text, z);
					if (p != null)
					{
						OverlayUtil.renderTextLocation(g, p, text, color);
					}
					z += 16;
				}
			}
		}
		return null;
	}
}

package com.marvinight.myammo;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.WildcardMatcher;

@PluginDescriptor(
	name = "My Ammo Highlighter",
	description = "Highlights your own ammo (bolts, arrows, darts...) lying on the ground",
	tags = {"ammo", "bolts", "arrows", "darts", "ranged", "ground", "highlight"}
)
public class MyAmmoPlugin extends Plugin
{
	/** Equipment ("worn") item container id. */
	private static final int WORN_CONTAINER = 94;

	private static final String[] THROWN_KEYWORDS = {
		"dart", "knife", "javelin", "thrownaxe", "chinchompa", "toktz-xil-ul"
	};

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ItemManager itemManager;
	@Inject private OverlayManager overlayManager;
	@Inject private MyAmmoOverlay overlay;
	@Inject private MyAmmoConfig config;

	/** Every ammo id you've had equipped this session, so piles still highlight after your quiver runs dry. */
	private final Set<Integer> ammoIds = new HashSet<>();
	private final Map<TileItem, GroundAmmo> groundAmmo = new LinkedHashMap<>();
	private List<String> extraPatterns = new ArrayList<>();

	@Value
	static class GroundAmmo
	{
		Tile tile;
		TileItem item;
		String name;
	}

	@Provides
	MyAmmoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MyAmmoConfig.class);
	}

	@Override
	protected void startUp()
	{
		parseExtraPatterns();
		overlayManager.add(overlay);
		clientThread.invokeLater(this::refreshEquipment);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		groundAmmo.clear();
		ammoIds.clear();
	}

	Collection<GroundAmmo> getGroundAmmo()
	{
		return groundAmmo.values();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == WORN_CONTAINER)
		{
			refreshEquipment();
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		TileItem item = event.getItem();
		if (isMyAmmo(item))
		{
			String name = itemManager.getItemComposition(item.getId()).getName();
			groundAmmo.put(item, new GroundAmmo(event.getTile(), item, name));
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		groundAmmo.remove(event.getItem());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Items re-fire ItemSpawned after a region load, so start clean.
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			groundAmmo.clear();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (MyAmmoConfig.GROUP.equals(event.getGroup()))
		{
			parseExtraPatterns();
		}
	}

	private void refreshEquipment()
	{
		ItemContainer worn = client.getItemContainer(WORN_CONTAINER);
		if (worn == null)
		{
			return;
		}

		Item ammo = worn.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
		if (ammo != null && ammo.getId() > 0)
		{
			ammoIds.add(ammo.getId());
		}

		if (config.trackThrown())
		{
			Item weapon = worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
			if (weapon != null && weapon.getId() > 0 && isThrownWeapon(weapon.getId()))
			{
				ammoIds.add(weapon.getId());
			}
		}
	}

	private boolean isThrownWeapon(int itemId)
	{
		String name = itemManager.getItemComposition(itemId).getName().toLowerCase();
		for (String keyword : THROWN_KEYWORDS)
		{
			if (name.contains(keyword))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isMyAmmo(TileItem item)
	{
		if (config.onlyMine() && item.getOwnership() != TileItem.OWNERSHIP_SELF)
		{
			return false;
		}

		if (ammoIds.contains(item.getId()))
		{
			return true;
		}

		if (!extraPatterns.isEmpty())
		{
			String name = itemManager.getItemComposition(item.getId()).getName();
			for (String pattern : extraPatterns)
			{
				if (WildcardMatcher.matches(pattern, name))
				{
					return true;
				}
			}
		}
		return false;
	}

	private void parseExtraPatterns()
	{
		List<String> patterns = new ArrayList<>();
		for (String part : config.extraItems().split(","))
		{
			String trimmed = part.trim();
			if (!trimmed.isEmpty())
			{
				patterns.add(trimmed);
			}
		}
		extraPatterns = patterns;
	}
}

package com.marvinight.myammo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Run this main() (or ./gradlew run) to start RuneLite with the plugin loaded. */
public class MyAmmoPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MyAmmoPlugin.class);
		RuneLite.main(args);
	}
}
